param([string]$ProjectRoot=(Join-Path $PSScriptRoot '..'),[string]$BuildRoot='',[ValidateRange(3,20)][int]$SampleSeconds=5)
$ErrorActionPreference='Stop';$ProjectRoot=[IO.Path]::GetFullPath($ProjectRoot);if(!$BuildRoot){$BuildRoot=Join-Path $ProjectRoot out/staging};$BuildRoot=[IO.Path]::GetFullPath($BuildRoot)
Add-Type -Path (Join-Path $PSScriptRoot PrivateDesktop.cs);Add-Type -Path (Join-Path $PSScriptRoot RenderedPixels.cs);Add-Type -Path (Join-Path $PSScriptRoot NativeChatTest.cs)
$root=Join-Path $ProjectRoot ('artifacts/rendering-'+[Guid]::NewGuid().ToString('N'));New-Item -ItemType Directory -Force $root|Out-Null;$desktop=$null;$service=$null;$checks=0;$samples=@()
$env:HIBERNATION_SESSION_KEY='rendering-fixture';$env:TEMP=Join-Path $BuildRoot tmp;$env:TMP=$env:TEMP
function Check($Value,$Name){if(!$Value){throw "CHECK FAILED: $Name"};$script:checks++;Write-Output "PASS $Name"}
function Wait-For([scriptblock]$Probe,$Name){$end=[DateTime]::UtcNow.AddSeconds(25);while([DateTime]::UtcNow-lt$end){if(& $Probe){return};Start-Sleep -Milliseconds 30};throw "TIMEOUT $Name"}
function Api($Path,$Data=$null){$a=@{Uri=$script:origin+$Path;Headers=@{Authorization='Bearer rendering-fixture'};TimeoutSec=10};if($null-ne$Data){$a.Method='Post';$a.ContentType='application/json';$a.Body=[Text.Encoding]::UTF8.GetBytes(($Data|ConvertTo-Json -Depth 35 -Compress))};Invoke-RestMethod @a}
function Plugin($Name,$Arguments=@{}){$null=Api '/api/plugin/test' @{tool=$Name;args=$Arguments};Wait-For {$script:receipt=Api '/api/plugin/result';$script:receipt.state-in@('succeeded','failed')} $Name;Check $receipt.result.ok "completed local tool $Name"}
function Current($Capabilities,$Id){@($Capabilities.plugins|Where-Object id -eq $Id)[0].current}
function Read-Sample($Name){Start-Sleep -Milliseconds 300;$before=Api '/api/capabilities';$service.Refresh();$cpu=$service.TotalProcessorTime.TotalMilliseconds;$watch=[Diagnostics.Stopwatch]::StartNew();Start-Sleep -Seconds $SampleSeconds;$service.Refresh();$cpu=$service.TotalProcessorTime.TotalMilliseconds-$cpu;$after=Api '/api/capabilities';$widget=(Current $after widget).paint_count-(Current $before widget).paint_count;$world=(Current $after habitat).paint_count-(Current $before habitat).paint_count;$sample=@{phase=$Name;seconds=$watch.Elapsed.TotalSeconds;cpuMs=$cpu;singleCorePercent=100*$cpu/$watch.Elapsed.TotalMilliseconds;widgetPaints=$widget;worldPaints=$world};$script:samples+=@($sample);return $sample}
try{
 $cfg=Get-Content (Join-Path $ProjectRoot config/example.json) -Raw|ConvertFrom-Json -AsHashtable;$cfg.dataRoot=Join-Path $root data;$cfg.characterRoot=Join-Path $ProjectRoot character;$cfg.uiRoot=Join-Path $ProjectRoot ui;$cfg.pluginRoot=Join-Path $BuildRoot plugins;$cfg.profiles=@($cfg.profiles[0]);$cfg.frontend=@{startupAnimation=$false;reducedMotion=$true};$cfg.solitudeIntervalMs=604800000;$cfg.idleBeforeSolitudeMs=86400000;$cfg.plugins=@{widget=@{enabled=$true;roam=$false;reducedMotion=$true;skin='dinosaur';palette='forest';size=112};habitat=@{enabled=$true;autoSpawn=$false;autoInteract=$false;reducedMotion=$true}}
 $cfg|ConvertTo-Json -Depth 30|Set-Content (Join-Path $root config.json) -Encoding utf8;$desktop=[PrivateDesktop]::new((Join-Path $BuildRoot hibernation-agent.exe),(Join-Path $root config.json),(Join-Path $root ready.json),$ProjectRoot);$service=$desktop.Child;Wait-For {if($service.HasExited){throw 'private render process exited'};Test-Path (Join-Path $root ready.json)} 'ready';$script:origin='http://127.0.0.1:'+((Get-Content (Join-Path $root ready.json) -Raw|ConvertFrom-Json).port)
 Plugin 'habitat.place' @{kind='berry'};Plugin 'habitat.place' @{kind='seed'};Plugin 'habitat.place' @{kind='paper_star'};$caps=Api '/api/capabilities';Check ($null-ne(Current $caps widget).paint_count-and$null-ne(Current $caps habitat).paint_count) 'actual native paint counts are present'
 $quiet=Read-Sample 'reduced_idle';Check ($quiet.worldPaints-eq0-and$quiet.widgetPaints-le6) 'unchanged reduced-motion surfaces do not continuously redraw'
 $window=$desktop.Find('HibernationDinosaurOverlay');$image=$desktop.CaptureClient($window);$bounds=[RenderedPixels]::Avatar($image.Bgra,$image.Width,$image.Height);Check ($bounds.Count-gt100) 'owned widget buffer contains actual nonempty avatar pixels'
 $settings=(Api '/api/dashboard').settings;$settings.plugins.widget.reducedMotion=$false;$settings.plugins.habitat.reducedMotion=$false;$null=Api '/api/settings' @{settings=$settings};$animated=Read-Sample 'animated_idle';if((Current (Api '/api/capabilities') widget).reduced_motion){Check ($animated.widgetPaints-le6-and$animated.worldPaints-eq0) 'system reduced motion remains authoritative'}else{Check ($animated.widgetPaints-gt4-and$animated.widgetPaints-le(35*$SampleSeconds)) 'normal animation remains active with a bounded paint rate';Check ($animated.worldPaints-gt0-and$animated.worldPaints-lt(12*$SampleSeconds)) 'objects redraw only on changed visible animation frames'}
 $before=Current (Api '/api/capabilities') widget;Plugin 'widget.move' @{x=.85;y=$before.y};$moving=Read-Sample 'walking';$null=Api '/api/control' @{paused=$true};Start-Sleep -Milliseconds 250;$position=Current (Api '/api/capabilities') widget;$image=$desktop.CaptureClient($window);$bounds=[RenderedPixels]::Avatar($image.Bgra,$image.Width,$image.Height);$x=$position.x*($image.Width-112);$y=$position.y*($image.Height-112);Check (($position.x-$before.x)*($image.Width-112)-gt80) 'bounded redraw preserves actual gradual travel';Check ($bounds.Count-gt100-and$bounds.Left-ge($x-25)-and$bounds.Right-le($x+137)-and$bounds.Top-ge($y-25)-and$bounds.Bottom-le($y+137)) 'moving avatar erases old pixels and keeps all current pixels inside its dirty bounds'
 $paused=Read-Sample 'paused';Check ($paused.widgetPaints-eq0-and$paused.worldPaints-eq0) 'paused surfaces do not request recurring paints'
 [ChatWindowTest]::UseWindowCoordinates($window);$mouseX=[int]($x+56);$mouseY=[int]($y+56);$edge=$image.Width-57;$null=[ChatWindowTest]::Send($window,0x201,0,($mouseY-shl16)-bor$mouseX);$null=[ChatWindowTest]::Send($window,0x200,1,($mouseY-shl16)-bor$edge);$null=[ChatWindowTest]::Send($window,0x202,0,($mouseY-shl16)-bor$edge);Start-Sleep -Milliseconds 150;$prior=Current (Api '/api/capabilities') widget;$settings=(Api '/api/dashboard').settings;$settings.plugins.widget.skin='lumen';$settings.plugins.widget.palette='amber';$settings.plugins.widget.size=240;$null=Api '/api/settings' @{settings=$settings};Wait-For {(Current (Api '/api/capabilities') widget).paint_count-gt$prior.paint_count} 'paused appearance redraw';$large=Current (Api '/api/capabilities') widget;Check ($large.x-le1-and$large.y-le1-and$large.skin-eq'lumen') 'live resizing near the screen edge remains inside normalized bounds';$image=$desktop.CaptureClient($window);$bounds=[RenderedPixels]::Avatar($image.Bgra,$image.Width,$image.Height);$newX=$large.x*($image.Width-240);$newY=$large.y*($image.Height-240);Check ($bounds.Count-gt100-and$bounds.Left-ge($newX-25)-and$bounds.Right-le($newX+265)-and$bounds.Top-ge($newY-25)-and$bounds.Bottom-le($newY+265)) 'paused appearance change repaints and clears the previous shape';Check ((Api '/api/chat').paused-and(Api '/api/chat').messages.Count-eq0) 'rendering settings preserve pause and create no conversation entries'
 $null=Api '/api/shutdown' @{};Check ($service.WaitForExit(10000)-and$service.ExitCode-eq0) 'rendering fixture exits cleanly';@{completed=$true;checks=$checks;samples=$samples;root=$root;timestamp=[DateTime]::UtcNow.ToString('O')}|ConvertTo-Json -Depth 10|Set-Content (Join-Path $root acceptance.json);Write-Output "Rendering checks passed: $checks checks. Evidence: $root"
}finally{if($service-and!$service.HasExited){try{$null=Api '/api/shutdown' @{};$service.WaitForExit(5000)|Out-Null}catch{}};if($desktop){$desktop.Dispose()}}

